SELECT COUNT(*)
FROM stock_daily_quote
WHERE trade_date = #{tradeDate}

SELECT trade_date, turnover_amount_yuan FROM stock_daily_quote WHERE trade_date IN
#{tradeDate}
AND ( stock_code LIKE '0%' OR stock_code LIKE '3%' OR stock_code LIKE '6%' ) ORDER BY trade_date DESC

SELECT stock_code, trade_date, close_price FROM stock_daily_quote WHERE trade_date IN
#{tradeDate}
ORDER BY trade_date DESC, stock_code ASC

SELECT stock_code, trade_date, turnover_amount_yuan FROM stock_daily_quote WHERE trade_date IN
#{tradeDate}
AND stock_code IN
#{stockCode}
ORDER BY trade_date, stock_code
